#!/usr/bin/env python3
"""
Round 128b (culprits), 2 October 2026. Needs round 127b.

Three national environmental-crime registers under Environmental crime.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

HEAD = "## Round 128b (2 October)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round128b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 127b" not in text:
        sys.exit("round128b: round 127b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round128b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round128b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round128b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


NOTE = '## Round 128b (2 October)\n\nNeeds round 127b. Tiles patch round128b_tiles.py beside it. No app.js?v= bump.\n\n- National environmental-crime registers, from what probe/enforcement shows\n  they hold (tiles scripts/enforcement_registers.py, weekly; unbuilt ones\n  daily), under Environmental crime after IBAMA, route pmtiles with boxes:\n  - ea_enforcement: Environment Agency enforcement actions, England (8,288\n    in the probe), placed at the postcode ending each address (postcodes.io;\n    terminated postcodes by their last position). OGL v3.\n  - canada_offenders: Environmental Offenders Registry export (~290), placed\n    at the offence town by Nominatim, else the company\'s town (box says).\n  - epa_cases: EPA ECHO case files (136,753 cases), one point per named\n    facility at its ZIP code centre (Census gazetteer; ECHO gives no\n    coordinates), with violations, laws, pollutants, defendants, programs.\n  - Counts and what was not placed: enforcement/registers.json.\n- Not mapped, and why: EA prosecutions ("All rights reserved", no licence:\n  needs permission); Chile SMA (PDFs in Drive folders); NSW EPA (search page\n  only); Colombia (no sanctions table found); PROFEPA, OEFA, Ireland EPA,\n  SEPA (addresses refused or gone). IUU vessels already mapped.\n- The script was tested on made-up rows only (the registers are blocked\n  from the sandbox): read the refresh log and registers.json.\n\n'
DIFF = ''

if __name__ == "__main__":
    main()
